internal static class CompanionProgram {
 internal static readonly string Root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CompagnonDofus");
 internal static readonly string Installed=Path.Combine(Root,"App","CompagnonDofus.exe");
 [STAThread]static int Main(string[] args){try{SongesCapture.SetProcessDPIAware();if(args.Length==2&&args[0]=="--songes-ocr-test")return SongesOcrAcceptance.Run(args[1]);if(args.Length==2&&args[0]=="--ganymede-reader-test")return StandaloneTests.ReaderTest(args[1]);if(args.Length==2&&args[0]=="--self-test")return StandaloneTests.Run(args[1]);if(args.Contains("--install")){Install();return 0;}bool created;using(var mutex=new Mutex(true,"Local\\CompagnonDofus.Standalone",out created)){if(!created){MessageBox.Show("Le compagnon est déjà ouvert. Retrouvez-le avec Alt + Tab.","Compagnon Dofus");return 0;}var app=new Application{ShutdownMode=ShutdownMode.OnMainWindowClose};app.DispatcherUnhandledException+=delegate(object sender,System.Windows.Threading.DispatcherUnhandledExceptionEventArgs e){MessageBox.Show(e.Exception.Message,"Compagnon Dofus");e.Handled=true;};var overlay=new CompanionWindow(new Store(Path.Combine(Root,"Data")));app.Run(overlay);return 0;}}catch(Exception ex){MessageBox.Show("Le compagnon n’a pas pu démarrer.\n"+ex.Message+"\n\nVos données : "+Root,"Compagnon Dofus",MessageBoxButton.OK,MessageBoxImage.Error);return 1;}}
 internal static void Install(){Directory.CreateDirectory(Path.GetDirectoryName(Installed));string source=Assembly.GetExecutingAssembly().Location;if(!String.Equals(Path.GetFullPath(source),Path.GetFullPath(Installed),StringComparison.OrdinalIgnoreCase)){var temporary=Installed+".new";File.Copy(source,temporary,true);if(File.Exists(Installed))File.Replace(temporary,Installed,null);else File.Move(temporary,Installed);}Shortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"Compagnon Dofus.lnk"));string menu=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"Compagnon Dofus");Directory.CreateDirectory(menu);Shortcut(Path.Combine(menu,"Compagnon Dofus.lnk"));MessageBox.Show("Compagnon Dofus installé.\nLe raccourci est disponible sur le bureau et dans le menu Démarrer.\n\nAucune donnée de Mon espace n’a été modifiée.","Compagnon Dofus");Process.Start(new ProcessStartInfo(Installed){UseShellExecute=true});}
 static void Shortcut(string file){object shell=null,link=null;try{var type=Type.GetTypeFromProgID("WScript.Shell");shell=Activator.CreateInstance(type);link=type.InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{file});var lt=link.GetType();lt.InvokeMember("TargetPath",BindingFlags.SetProperty,null,link,new object[]{Installed});lt.InvokeMember("WorkingDirectory",BindingFlags.SetProperty,null,link,new object[]{Path.GetDirectoryName(Installed)});lt.InvokeMember("Description",BindingFlags.SetProperty,null,link,new object[]{"Compagnon Dofus · guides Tougli"});lt.InvokeMember("IconLocation",BindingFlags.SetProperty,null,link,new object[]{Installed+",0"});lt.InvokeMember("Save",BindingFlags.InvokeMethod,null,link,null);}finally{if(link!=null)System.Runtime.InteropServices.Marshal.FinalReleaseComObject(link);if(shell!=null)System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);}}
